def min_remaining_space(V: int, n: int, volumes: list) -> int:
    # Handle edge cases
    if V <= 0:
        return max(0, V)

    # Create a boolean DP array where dp[vol] represents whether a volume of 'vol' can be achieved
    dp = [False] * (V + 1)
    dp[0] = True

    for vol in volumes[:n]:  # Only consider the first n items
        # Traverse from V down to vol to avoid using the same item multiple times
        for v in range(V, vol - 1, -1):
            if dp[v - vol]:
                dp[v] = True

    # Find the maximum volume that can be occupied
    max_occupied = 0
    for v in range(V, -1, -1):
        if dp[v]:
            max_occupied = v
            break

    return V - max_occupied
