def minimum_students_to_leave(heights):
    """
    Calculate the minimum number of students that need to leave to form a choir formation.

    :param heights: A list of student heights.
    :return: The minimum number of students that need to leave.
    """
    if not heights:
        return 0

    n = len(heights)

    # Calculate the longest increasing subsequence ending at each position
    inc = [0] * n
    for i in range(n):
        inc[i] = 1
        for j in range(i):
            if heights[j] < heights[i]:
                inc[i] = max(inc[i], inc[j] + 1)

    # Calculate the longest decreasing subsequence starting at each position
    dec = [0] * n
    for i in range(n - 1, -1, -1):
        dec[i] = 1
        for j in range(i + 1, n):
            if heights[j] < heights[i]:
                dec[i] = max(dec[i], dec[j] + 1)

    # Find the maximum choir formation size
    max_size = 0
    for i in range(n):
        max_size = max(max_size, inc[i] + dec[i] - 1)

    return n - max_size
